const cases = [];

function clone(x){ return JSON.parse(JSON.stringify(x)); }

function apply(snapshot, simulateConflict=false) {
  const prior = clone(snapshot);
  const intended = clone(snapshot);
  const observedBeforeWrite = clone(snapshot);
  let result = 'PASS';
  let writeConflict = false;

  if (simulateConflict) {
    observedBeforeWrite.assets.a.version += 1;
  }

  if (observedBeforeWrite.assets.a.version !== prior.assets.a.version) {
    writeConflict = true;
    result = 'BLOCKED';
    return { prior, intended: prior, observed_post_state: observedBeforeWrite, result, writeConflict };
  }

  if (intended.assets.a.release_gate === 'Block') {
    result = 'PARTIAL';
  } else {
    intended.assets.a.release_gate = 'Review';
    intended.assets.a.reconciliation_status = 'In progress';
    intended.assets.a.version += 1;
  }

  const eid = intended.assets.a.endpoint_id;
  const endpoint = intended.endpoints[eid];
  if (!endpoint) {
    result = 'PARTIAL';
  } else if (endpoint.release_gate === 'Block') {
    result = 'PARTIAL';
  } else {
    endpoint.release_gate = 'Review';
    endpoint.copy_state = 'Review Needed';
    endpoint.version += 1;
  }

  const observedPostState = clone(intended);
  return { prior, intended, observed_post_state: observedPostState, result, writeConflict };
}

const base = {
  assets: {
    a: {
      release_gate: 'Pass',
      reconciliation_status: 'Done',
      endpoint_id: 'e',
      version: 1
    }
  },
  endpoints: {
    e: {
      release_gate: 'Pass',
      copy_state: 'Reconciled',
      version: 1
    }
  }
};

const normal = apply(base, false);
cases.push({
  id: 'normal_read_write_readback',
  pass:
    normal.prior.assets.a.release_gate === 'Pass' &&
    normal.intended.assets.a.release_gate === 'Review' &&
    normal.observed_post_state.assets.a.release_gate === 'Review' &&
    normal.observed_post_state.endpoints.e.release_gate === 'Review' &&
    normal.writeConflict === false
});

const conflict = apply(base, true);
cases.push({
  id: 'optimistic_conflict_blocks_write',
  pass:
    conflict.result === 'BLOCKED' &&
    conflict.writeConflict === true &&
    conflict.intended.assets.a.release_gate === 'Pass'
});

const blocked = clone(base);
blocked.assets.a.release_gate = 'Block';
const blockedResult = apply(blocked, false);
cases.push({
  id: 'blocked_asset_preserved',
  pass:
    blockedResult.result === 'PARTIAL' &&
    blockedResult.observed_post_state.assets.a.release_gate === 'Block'
});

const passDoneProhibition = ![
  normal.observed_post_state.assets.a.release_gate,
  normal.observed_post_state.endpoints.e.release_gate
].includes('Pass') && normal.observed_post_state.assets.a.reconciliation_status !== 'Done';
cases.push({id:'pass_done_prohibition', pass:passDoneProhibition});

const failed = cases.filter(c=>!c.pass);
if (failed.length) throw new Error('SHADOW_ADAPTER_CONFORMANCE_FAILED:'+JSON.stringify(failed));

return [{json:{
  harness:'NDR_PUBLIC_CHANGE_PROPAGATION_N8N_SHADOW_ADAPTER_V1',
  mode:'SHADOW_ONLY',
  adapter_surface:'SHADOW_ONLY',
  runtime_state:'NOT_DEPLOYED',
  promotion_eligible:false,
  authority_effect:'NONE_DEPLOYMENT_EVIDENCE_ONLY',
  read_before_write:'PASS',
  post_write_readback:'PASS',
  block_preservation:'PASS',
  pass_done_prohibition:'PASS',
  write_conflict_detection:'PASS',
  total:cases.length,
  passed:cases.length,
  failed:0,
  result:'PASS',
  cases
}}];
